export const grammarLessonsAstra: GrammarLesson[] = [{"id":"ast-grammar-0","title":"Sentence structure","category":"Sentence structure","content":[{"heading":"Sentence structure","body":"A complete sentence normally needs a subject and a finite verb. Check for fragments after linking words.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying sentence structure? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":1},{"id":"ast-grammar-1","title":"Subject–verb agreement","category":"Subject–verb agreement","content":[{"heading":"Subject–verb agreement","body":"Match the verb with the subject, not a nearby noun: “The number of students is increasing.”\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying subject–verb agreement? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":2},{"id":"ast-grammar-2","title":"Articles","category":"Articles","content":[{"heading":"Articles","body":"Use a/an with a singular countable noun introduced generally. Use the when the reference is specific or already identified.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying articles? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":3},{"id":"ast-grammar-3","title":"Tenses","category":"Tenses","content":[{"heading":"Tenses","body":"Choose tense from the time reference. Use the past for a completed period and avoid switching without a reason.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying tenses? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":4},{"id":"ast-grammar-4","title":"Conditionals","category":"Conditionals","content":[{"heading":"Conditionals","body":"Use if + present with will for a realistic future condition. Use if + past with would for a hypothetical situation.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying conditionals? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":5},{"id":"ast-grammar-5","title":"Relative clauses","category":"Relative clauses","content":[{"heading":"Relative clauses","body":"Use relative clauses to add relevant information. Non-defining clauses need commas and cannot use “that”.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying relative clauses? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":6},{"id":"ast-grammar-6","title":"Punctuation","category":"Punctuation","content":[{"heading":"Punctuation","body":"Do not join two independent sentences with only a comma. Use a full stop, a semicolon or an appropriate conjunction.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying punctuation? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":7},{"id":"ast-grammar-7","title":"Complex sentences","category":"Complex sentences","content":[{"heading":"Complex sentences","body":"Use subordinate clauses to express genuine relationships such as contrast or cause. Complexity should clarify meaning.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying complex sentences? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":8},{"id":"ast-grammar-8","title":"Linking devices","category":"Linking devices","content":[{"heading":"Linking devices","body":"Although introduces a clause; however usually links separate statements. They are not interchangeable in the same structure.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying linking devices? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":9},{"id":"ast-grammar-9","title":"Prepositions","category":"Prepositions","content":[{"heading":"Prepositions","body":"Learn common combinations such as interested in, depend on and responsible for. Avoid translating them word for word.\n\nTry it: apply this strategy to one original practice question. Explain your choice before checking the answer.\n\nReview: identify the exact evidence or language pattern that supports your answer. If you made a mistake, retry without looking at the explanation.","tips":["Check yourself: Which is the best next step after studying prepositions? — Answer: Apply the strategy and check the evidence"]}],"orderIndex":10},{"id":"ast-grammar-deep-02","title":"Present simple routine","category":"Present simple routine","content":[{"heading":"Present simple routine","body":"Use the present simple for regular routines. A third-person singular subject takes the -s form.\n\nWorked example: The library welcomes visitors every weekday.\n\nWhy this works: Use the present simple for regular routines. A third-person singular subject takes the -s form. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “welcome” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library ____ visitors every weekday. — Answer: welcomes"]}],"orderIndex":11},{"id":"ast-grammar-deep-03","title":"Past simple","category":"Past simple","content":[{"heading":"Past simple","body":"A finished past-time expression such as last year normally requires the past simple.\n\nWorked example: The library opened a new room last year.\n\nWhy this works: A finished past-time expression such as last year normally requires the past simple. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “opens” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library ____ a new room last year. — Answer: opened"]}],"orderIndex":12},{"id":"ast-grammar-deep-04","title":"Present perfect","category":"Present perfect","content":[{"heading":"Present perfect","body":"Use the present perfect for an unfinished period connected to now. So far signals the period is still open.\n\nWorked example: The library has organised three events so far this month.\n\nWhy this works: Use the present perfect for an unfinished period connected to now. So far signals the period is still open. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “organised” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library ____ three events so far this month. — Answer: has organised"]}],"orderIndex":13},{"id":"ast-grammar-deep-05","title":"Past perfect","category":"Past perfect","content":[{"heading":"Past perfect","body":"The past perfect places one event before another past event. The later event normally uses the past simple.\n\nWorked example: The library had closed before we arrived.\n\nWhy this works: The past perfect places one event before another past event. The later event normally uses the past simple. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “arrive” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library had closed before we ____. — Answer: arrived"]}],"orderIndex":14},{"id":"ast-grammar-deep-06","title":"Present continuous","category":"Present continuous","content":[{"heading":"Present continuous","body":"At the moment points to an activity in progress. Use be plus the -ing form.\n\nWorked example: The library is updating its booking system at the moment.\n\nWhy this works: At the moment points to an activity in progress. Use be plus the -ing form. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “updates” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library ____ its booking system at the moment. — Answer: is updating"]}],"orderIndex":15},{"id":"ast-grammar-deep-07","title":"Past continuous","category":"Past continuous","content":[{"heading":"Past continuous","body":"Use the past continuous for the background activity and the past simple for the event occurring during it.\n\nWorked example: The library was closing when the visitors arrived.\n\nWhy this works: Use the past continuous for the background activity and the past simple for the event occurring during it. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “were arrive” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library was closing when the visitors ____. — Answer: arrived"]}],"orderIndex":16},{"id":"ast-grammar-deep-08","title":"Future arrangements","category":"Future arrangements","content":[{"heading":"Future arrangements","body":"The present continuous can describe an arranged future event. The time reference must agree with that meaning.\n\nWorked example: The library is holding a meeting tomorrow.\n\nWhy this works: The present continuous can describe an arranged future event. The time reference must agree with that meaning. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “yesterday” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library is holding a meeting ____. — Answer: tomorrow"]}],"orderIndex":17},{"id":"ast-grammar-deep-09","title":"Since and for","category":"Since and for","content":[{"heading":"Since and for","body":"Since introduces a starting point. For introduces a duration, such as for ten years.\n\nWorked example: The library has served the community since 2015.\n\nWhy this works: Since introduces a starting point. For introduces a duration, such as for ten years. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “for” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library has served the community ____ 2015. — Answer: since"]}],"orderIndex":18},{"id":"ast-grammar-deep-10","title":"Duration with for","category":"Duration with for","content":[{"heading":"Duration with for","body":"A duration answers how long. Use for before a length of time, not since.\n\nWorked example: The library has used this system for five years.\n\nWhy this works: A duration answers how long. Use for before a length of time, not since. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “since” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library has used this system ____ five years. — Answer: for"]}],"orderIndex":19},{"id":"ast-grammar-deep-11","title":"First conditional","category":"First conditional","content":[{"heading":"First conditional","body":"A real future condition uses if plus present simple and will in the result clause.\n\nWorked example: If funding increases, the library will extend its hours.\n\nWhy this works: A real future condition uses if plus present simple and will in the result clause. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “would extend” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: If funding increases, the library ____ its hours. — Answer: will extend"]}],"orderIndex":20},{"id":"ast-grammar-deep-12","title":"Second conditional","category":"Second conditional","content":[{"heading":"Second conditional","body":"Use past simple plus would for a hypothetical present or future situation. The past form does not necessarily describe past time.\n\nWorked example: If the library had more funding, it would extend its hours.\n\nWhy this works: Use past simple plus would for a hypothetical present or future situation. The past form does not necessarily describe past time. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “will extend” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: If the library had more funding, it ____ its hours. — Answer: would extend"]}],"orderIndex":21},{"id":"ast-grammar-deep-13","title":"Third conditional","category":"Third conditional","content":[{"heading":"Third conditional","body":"Use had plus past participle and would have plus past participle for an unreal alternative to a past event.\n\nWorked example: If the library had received funding, it would have opened earlier.\n\nWhy this works: Use had plus past participle and would have plus past participle for an unreal alternative to a past event. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “will open” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: If the library had received funding, it ____ earlier. — Answer: would have opened"]}],"orderIndex":22},{"id":"ast-grammar-deep-14","title":"Unless","category":"Unless","content":[{"heading":"Unless","body":"Unless means if not. Here opening depends on completing the inspection.\n\nWorked example: The library will remain closed unless the inspection is completed.\n\nWhy this works: Unless means if not. Here opening depends on completing the inspection. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “because” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library will remain closed ____ the inspection is completed. — Answer: unless"]}],"orderIndex":23},{"id":"ast-grammar-deep-15","title":"Present passive","category":"Present passive","content":[{"heading":"Present passive","body":"Use be plus past participle when the subject receives the action. The partnership performs the action.\n\nWorked example: The library is managed by a local partnership.\n\nWhy this works: Use be plus past participle when the subject receives the action. The partnership performs the action. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “manages” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library ____ by a local partnership. — Answer: is managed"]}],"orderIndex":24},{"id":"ast-grammar-deep-16","title":"Past passive","category":"Past passive","content":[{"heading":"Past passive","body":"The subject receives the action, and a finished past date requires a past passive form.\n\nWorked example: The library was established in 1998.\n\nWhy this works: The subject receives the action, and a finished past date requires a past passive form. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “established” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library ____ in 1998. — Answer: was established"]}],"orderIndex":25},{"id":"ast-grammar-deep-17","title":"Modal passive","category":"Modal passive","content":[{"heading":"Modal passive","body":"After a modal, use the base form. A passive construction therefore uses modal plus be plus past participle.\n\nWorked example: The library must be inspected before the event.\n\nWhy this works: After a modal, use the base form. A passive construction therefore uses modal plus be plus past participle. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “inspect” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library must ____ before the event. — Answer: be inspected"]}],"orderIndex":26},{"id":"ast-grammar-deep-18","title":"Modal base form","category":"Modal base form","content":[{"heading":"Modal base form","body":"A modal such as can is followed by the base verb without -s or to.\n\nWorked example: The library can provide additional information.\n\nWhy this works: A modal such as can is followed by the base verb without -s or to. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “provides” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library can ____ additional information. — Answer: provide"]}],"orderIndex":27},{"id":"ast-grammar-deep-19","title":"Should have","category":"Should have","content":[{"heading":"Should have","body":"Should have plus past participle comments on an action that would have been preferable in the past.\n\nWorked example: The library should have announced the change earlier.\n\nWhy this works: Should have plus past participle comments on an action that would have been preferable in the past. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “announce” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library should have ____ the change earlier. — Answer: announced"]}],"orderIndex":28},{"id":"ast-grammar-deep-20","title":"Infinitive of purpose","category":"Infinitive of purpose","content":[{"heading":"Infinitive of purpose","body":"Use to plus base verb to express the purpose of an action.\n\nWorked example: The library introduced reminders to reduce missed bookings.\n\nWhy this works: Use to plus base verb to express the purpose of an action. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “for reduce” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library introduced reminders ____ missed bookings. — Answer: to reduce"]}],"orderIndex":29},{"id":"ast-grammar-deep-21","title":"Gerund after preposition","category":"Gerund after preposition","content":[{"heading":"Gerund after preposition","body":"A verb following a preposition normally takes the -ing form. By describes the method.\n\nWorked example: The library improved access by installing a ramp.\n\nWhy this works: A verb following a preposition normally takes the -ing form. By describes the method. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “install” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library improved access by ____ a ramp. — Answer: installing"]}],"orderIndex":30},{"id":"ast-grammar-deep-22","title":"Avoid plus gerund","category":"Avoid plus gerund","content":[{"heading":"Avoid plus gerund","body":"Avoid is followed by a noun or an -ing form, not a to-infinitive.\n\nWorked example: The library aims to avoid sharing personal details.\n\nWhy this works: Avoid is followed by a noun or an -ing form, not a to-infinitive. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “to share” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library aims to avoid ____ personal details. — Answer: sharing"]}],"orderIndex":31},{"id":"ast-grammar-deep-23","title":"Decide plus infinitive","category":"Decide plus infinitive","content":[{"heading":"Decide plus infinitive","body":"Decide is followed by a to-infinitive when the next verb describes the chosen action.\n\nWorked example: The library decided to extend its opening hours.\n\nWhy this works: Decide is followed by a to-infinitive when the next verb describes the chosen action. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “extending” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library decided ____ its opening hours. — Answer: to extend"]}],"orderIndex":32},{"id":"ast-grammar-deep-24","title":"Countable singular article","category":"Countable singular article","content":[{"heading":"Countable singular article","body":"A singular countable noun needs a determiner. New begins with a consonant sound, so use a.\n\nWorked example: The library has a new entrance.\n\nWhy this works: A singular countable noun needs a determiner. New begins with a consonant sound, so use a. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “an” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library has ____ new entrance. — Answer: a"]}],"orderIndex":33},{"id":"ast-grammar-deep-25","title":"An before vowel sounds","category":"An before vowel sounds","content":[{"heading":"An before vowel sounds","body":"Use an before a vowel sound. The choice depends on pronunciation, not only the written letter.\n\nWorked example: The library arranged an appointment for the visitor.\n\nWhy this works: Use an before a vowel sound. The choice depends on pronunciation, not only the written letter. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “a” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library arranged ____ appointment for the visitor. — Answer: an"]}],"orderIndex":34},{"id":"ast-grammar-deep-26","title":"Definite reference","category":"Definite reference","content":[{"heading":"Definite reference","body":"Use the when the reader can identify the noun from an earlier mention.\n\nWorked example: The library has a garden. The garden is open daily.\n\nWhy this works: Use the when the reader can identify the noun from an earlier mention. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “A” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library has a garden. ____ garden is open daily. — Answer: The"]}],"orderIndex":35},{"id":"ast-grammar-deep-27","title":"Uncountable information","category":"Uncountable information","content":[{"heading":"Uncountable information","body":"Information is normally uncountable. Use some information or a piece of information, not informations.\n\nWorked example: The library provides useful information.\n\nWhy this works: Information is normally uncountable. Use some information or a piece of information, not informations. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “informations” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library provides useful ____. — Answer: information"]}],"orderIndex":36},{"id":"ast-grammar-deep-28","title":"Much and many","category":"Much and many","content":[{"heading":"Much and many","body":"Equipment is uncountable. Use much or a little rather than many or a few.\n\nWorked example: The library does not have much spare equipment.\n\nWhy this works: Equipment is uncountable. Use much or a little rather than many or a few. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “many” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library does not have ____ spare equipment. — Answer: much"]}],"orderIndex":37},{"id":"ast-grammar-deep-29","title":"Few and little","category":"Few and little","content":[{"heading":"Few and little","body":"Complaints is a plural countable noun. Use few to describe a small number.\n\nWorked example: The library received very few complaints.\n\nWhy this works: Complaints is a plural countable noun. Use few to describe a small number. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “little” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library received very ____ complaints. — Answer: few"]}],"orderIndex":38},{"id":"ast-grammar-deep-30","title":"Fewer and less","category":"Fewer and less","content":[{"heading":"Fewer and less","body":"Use fewer with plural countable nouns when comparing quantities.\n\nWorked example: The library received fewer complaints than last year.\n\nWhy this works: Use fewer with plural countable nouns when comparing quantities. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “less” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library received ____ complaints than last year. — Answer: fewer"]}],"orderIndex":39},{"id":"ast-grammar-deep-31","title":"Comparative adjectives","category":"Comparative adjectives","content":[{"heading":"Comparative adjectives","body":"A short adjective such as large normally forms the comparative with -er. Than introduces the comparison.\n\nWorked example: The library is larger than the temporary venue.\n\nWhy this works: A short adjective such as large normally forms the comparative with -er. Than introduces the comparison. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “largest” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library is ____ than the temporary venue. — Answer: larger"]}],"orderIndex":40},{"id":"ast-grammar-deep-32","title":"Superlatives","category":"Superlatives","content":[{"heading":"Superlatives","body":"Use the superlative to compare one member with the whole group.\n\nWorked example: The library is the largest venue in the district.\n\nWhy this works: Use the superlative to compare one member with the whole group. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “larger” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library is the ____ venue in the district. — Answer: largest"]}],"orderIndex":41},{"id":"ast-grammar-deep-33","title":"As … as","category":"As … as","content":[{"heading":"As … as","body":"Equal comparisons use as plus adjective plus as. Do not mix as with than.\n\nWorked example: The library is as accessible as the central venue.\n\nWhy this works: Equal comparisons use as plus adjective plus as. Do not mix as with than. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “than” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library is as accessible ____ the central venue. — Answer: as"]}],"orderIndex":42},{"id":"ast-grammar-deep-34","title":"Adverbs of manner","category":"Adverbs of manner","content":[{"heading":"Adverbs of manner","body":"Use an adverb to describe how an action was performed. An adjective describes a noun.\n\nWorked example: The library handled the enquiry efficiently.\n\nWhy this works: Use an adverb to describe how an action was performed. An adjective describes a noun. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “efficient” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library handled the enquiry ____. — Answer: efficiently"]}],"orderIndex":43},{"id":"ast-grammar-deep-35","title":"Adjective after linking verb","category":"Adjective after linking verb","content":[{"heading":"Adjective after linking verb","body":"A linking verb such as remain connects the subject to an adjective describing its state.\n\nWorked example: The library remained accessible throughout the renovation.\n\nWhy this works: A linking verb such as remain connects the subject to an adjective describing its state. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “accessibly” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library remained ____ throughout the renovation. — Answer: accessible"]}],"orderIndex":44},{"id":"ast-grammar-deep-36","title":"Relative clauses for places","category":"Relative clauses for places","content":[{"heading":"Relative clauses for places","body":"Where introduces a clause describing what happens in a place. Which would require a different clause structure.\n\nWorked example: The library is a place where residents can meet.\n\nWhy this works: Where introduces a clause describing what happens in a place. Which would require a different clause structure. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “which” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library is a place ____ residents can meet. — Answer: where"]}],"orderIndex":45},{"id":"ast-grammar-deep-37","title":"Defining relative clauses","category":"Defining relative clauses","content":[{"heading":"Defining relative clauses","body":"That or which can be the subject of a relative clause referring to a thing. Do not add a second subject.\n\nWorked example: The library introduced a system that reduces delays.\n\nWhy this works: That or which can be the subject of a relative clause referring to a thing. Do not add a second subject. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “who” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library introduced a system ____ reduces delays. — Answer: that"]}],"orderIndex":46},{"id":"ast-grammar-deep-38","title":"Non-defining relative clauses","category":"Non-defining relative clauses","content":[{"heading":"Non-defining relative clauses","body":"Use which rather than that in a non-defining clause set off by commas.\n\nWorked example: The library, which opened recently, attracts many visitors.\n\nWhy this works: Use which rather than that in a non-defining clause set off by commas. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “that” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library, ____ opened recently, attracts many visitors. — Answer: which"]}],"orderIndex":47},{"id":"ast-grammar-deep-39","title":"Although","category":"Although","content":[{"heading":"Although","body":"Although introduces a clause with a subject and verb. Despite is followed by a noun or -ing phrase.\n\nWorked example: Although the library is small, it serves many residents.\n\nWhy this works: Although introduces a clause with a subject and verb. Despite is followed by a noun or -ing phrase. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “Despite” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: ____ the library is small, it serves many residents. — Answer: Although"]}],"orderIndex":48},{"id":"ast-grammar-deep-40","title":"Despite","category":"Despite","content":[{"heading":"Despite","body":"Despite is followed by a noun phrase. Limited funding is a noun phrase, not a full clause.\n\nWorked example: Despite limited funding, the library remained open.\n\nWhy this works: Despite is followed by a noun phrase. Limited funding is a noun phrase, not a full clause. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “Although” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: ____ limited funding, the library remained open. — Answer: Despite"]}],"orderIndex":49},{"id":"ast-grammar-deep-41","title":"Because and because of","category":"Because and because of","content":[{"heading":"Because and because of","body":"Use because of before a noun phrase and because before a full clause.\n\nWorked example: The library closed because of a power failure.\n\nWhy this works: Use because of before a noun phrase and because before a full clause. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “because” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library closed ____ a power failure. — Answer: because of"]}],"orderIndex":50},{"id":"ast-grammar-deep-42","title":"Therefore punctuation","category":"Therefore punctuation","content":[{"heading":"Therefore punctuation","body":"Therefore can connect two independent clauses when suitable punctuation is used. Here a semicolon precedes it.\n\nWorked example: The library was full; therefore, we used another venue.\n\nWhy this works: Therefore can connect two independent clauses when suitable punctuation is used. Here a semicolon precedes it. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “because” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library was full; ____, we used another venue. — Answer: therefore"]}],"orderIndex":51},{"id":"ast-grammar-deep-43","title":"Not only … but also","category":"Not only … but also","content":[{"heading":"Not only … but also","body":"Keep both halves of a paired structure. Not only is paired with but also.\n\nWorked example: The library is not only convenient but also affordable.\n\nWhy this works: Keep both halves of a paired structure. Not only is paired with but also. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “and also” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library is not only convenient ____ affordable. — Answer: but also"]}],"orderIndex":52},{"id":"ast-grammar-deep-44","title":"Either … or","category":"Either … or","content":[{"heading":"Either … or","body":"Either introduces one of two alternatives and is paired with or.\n\nWorked example: Either the library or the hall will host the meeting.\n\nWhy this works: Either introduces one of two alternatives and is paired with or. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “nor” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: Either the library ____ the hall will host the meeting. — Answer: or"]}],"orderIndex":53},{"id":"ast-grammar-deep-45","title":"Neither … nor","category":"Neither … nor","content":[{"heading":"Neither … nor","body":"Neither excludes both alternatives and is paired with nor.\n\nWorked example: Neither the library nor the hall is available.\n\nWhy this works: Neither excludes both alternatives and is paired with nor. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “or” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: Neither the library ____ the hall is available. — Answer: nor"]}],"orderIndex":54},{"id":"ast-grammar-deep-46","title":"Time prepositions","category":"Time prepositions","content":[{"heading":"Time prepositions","body":"Use at for a precise clock time, on for days and dates, and in for months or years.\n\nWorked example: The library opens at nine o’clock.\n\nWhy this works: Use at for a precise clock time, on for days and dates, and in for months or years. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “on” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library opens ____ nine o’clock. — Answer: at"]}],"orderIndex":55},{"id":"ast-grammar-deep-47","title":"Day prepositions","category":"Day prepositions","content":[{"heading":"Day prepositions","body":"Use on before a named day, including plural days that express a routine.\n\nWorked example: The library closes early on Fridays.\n\nWhy this works: Use on before a named day, including plural days that express a routine. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “at” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library closes early ____ Fridays. — Answer: on"]}],"orderIndex":56},{"id":"ast-grammar-deep-48","title":"Month prepositions","category":"Month prepositions","content":[{"heading":"Month prepositions","body":"Use in before a month when no specific date is given.\n\nWorked example: The library reopens in September.\n\nWhy this works: Use in before a month when no specific date is given. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “at” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library reopens ____ September. — Answer: in"]}],"orderIndex":57},{"id":"ast-grammar-deep-49","title":"Parallel structure","category":"Parallel structure","content":[{"heading":"Parallel structure","body":"Items in a parallel list should use matching grammatical forms. The first two verbs are base forms.\n\nWorked example: The library aims to inform, support and guide residents.\n\nWhy this works: Items in a parallel list should use matching grammatical forms. The first two verbs are base forms. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “guiding” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The library aims to inform, support and ____ residents. — Answer: guide"]}],"orderIndex":58},{"id":"ast-grammar-deep-50","title":"Reported statements","category":"Reported statements","content":[{"heading":"Reported statements","body":"A report viewed from a past point often shifts will to would. The next day preserves the reported time reference.\n\nWorked example: The director said that the library would be open the next day.\n\nWhy this works: A report viewed from a past point often shifts will to would. The next day preserves the reported time reference. Read the clause as a complete unit. Identify its subject, verb, time reference and any dependent phrase before applying the rule.\n\nCommon mistake: choosing “will be” merely because it sounds familiar. Check the function of the gap and read the entire sentence again. A correct word in another construction may be wrong here.\n\nPractice routine: complete the six contextual questions, explain why each alternative fails, then write two sentences about your own studies using the same construction.\n\nEditing strategy: find this pattern in a recent Writing or Speaking transcript. Correct one occurrence, reread the surrounding paragraph, and check that the meaning is unchanged. Revisit the exercise tomorrow without looking at the rule.","tips":["Check yourself: The director said that the library ____ open the next day. — Answer: would be"]}],"orderIndex":59}];
